-- Scourge Invasion rework: align data with AzerothCore reference implementation
-- 1) creature_template fixes (invisible relays/proxies/spawners/finders must be unselectable,
--    finder must not carry the old npc_si_controller script)
UPDATE `creature_template` SET `unit_flags` = 33554432 WHERE `entry` IN (16306,16336,16338,16356,16386,16398,16401,16421);
UPDATE `creature_template` SET `ScriptName` = '' WHERE `entry` = 16356;
UPDATE `creature_template` SET `npcflag` = 0 WHERE `entry` IN (16136,16172);
UPDATE `creature_template` SET `flags_extra` = 2 WHERE `entry` IN (16421,16230);
UPDATE `creature_template` SET `minlevel` = 1, `maxlevel` = 1 WHERE `entry` = 16401;
UPDATE `creature_template` SET `minlevel` = 70, `maxlevel` = 70 WHERE `entry` = 16394;
UPDATE `creature_template` SET `minlevel` = 63, `maxlevel` = 63 WHERE `entry` = 16383;
UPDATE `creature_template` SET `minlevel` = 71, `maxlevel` = 71 WHERE `entry` = 16380;
UPDATE `creature_template` SET `unit_flags` = 256 WHERE `entry` IN (16431,16531);

-- Remove the obsolete SI controller spawn (manager now ticks from the WorldScript)
DELETE FROM `game_event_creature` WHERE `guid` = 265135;
DELETE FROM `creature` WHERE `guid` = 265135;

-- 2) Necropolis gameobject scales
UPDATE `gameobject_template` SET `size` = 2.5 WHERE `entry` = 181215;
UPDATE `gameobject_template` SET `size` = 3.5 WHERE `entry` = 181223;
UPDATE `gameobject_template` SET `size` = 1.5 WHERE `entry` = 181373;
UPDATE `gameobject_template` SET `size` = 2.0 WHERE `entry` = 181374;

-- 3) Spell target conditions for the communication chain
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (28032,28056,28078,28281,28326,28364,28365,28366,28367,28373,31315);

-- 4) Scourge Invasion minion finder spawns (ported from AzerothCore, guid range 300000+)
DELETE `gec` FROM `game_event_creature` `gec` JOIN `creature` `c` ON `c`.`guid` = `gec`.`guid` WHERE `c`.`id` = 16356;
DELETE FROM `creature` WHERE `id` = 16356;
DELETE FROM `game_event_creature` WHERE `guid` BETWEEN 300000 AND 301128;
DELETE FROM `creature` WHERE `guid` BETWEEN 300000 AND 301128;











-- 5) Pallid Horror city attack waypoint paths
DELETE FROM `waypoint_data` WHERE `id` IN (163941,163942,163943,163944);


-- 6) Shadow of Doom C++ script + spawn texts (TC SmartAI cannot use action 18/19)
DELETE FROM `smart_scripts` WHERE `entryorguid` = 16143 AND `source_type` = 0;
UPDATE `creature_template` SET `AIName` = '', `ScriptName` = 'npc_shadow_of_doom' WHERE `entry` = 16143;

DELETE FROM `creature_text` WHERE `CreatureID` = 16143;

DELETE FROM `creature_text` WHERE `CreatureID` = 10181 AND `GroupID` = 3;

-- 7) Reset runtime state so the rework starts clean (victories are kept)
UPDATE `scourge_invasion_state` SET `remainingNecropoli` = 0, `attackTimer` = 0;
